function add_page_object(obj::wxPropertyGridManager, label::AbstractString, bitmap::Union{wxBitmapBundle, Nothing}, page::Union{wxPropertyGridPage, Nothing})
    label_ws = wxString(label)
    bitmap_ptr = isnothing(bitmap) ? C_NULL : bitmap.ptr
    page_ptr = isnothing(page) ? C_NULL : page.ptr
    _result = try
        _wx_wrap(wxPropertyGridPage, KwxFFI.wxPropertyGridManager_AddPageObject(obj.ptr, label_ws.ptr, bitmap_ptr, page_ptr))
    finally
        Base.delete!(label_ws)
    end
    return _result
end

function insert_page_object(obj::wxPropertyGridManager, index::Integer, label::AbstractString, bitmap::Union{wxBitmapBundle, Nothing}, page::Union{wxPropertyGridPage, Nothing})
    label_ws = wxString(label)
    bitmap_ptr = isnothing(bitmap) ? C_NULL : bitmap.ptr
    page_ptr = isnothing(page) ? C_NULL : page.ptr
    _result = try
        _wx_wrap(wxPropertyGridPage, KwxFFI.wxPropertyGridManager_InsertPageObject(obj.ptr, Cint(index), label_ws.ptr, bitmap_ptr, page_ptr))
    finally
        Base.delete!(label_ws)
    end
    return _result
end

